# -*- coding: utf-8 -*-
S = "перепись показываемого LaTeX по всему банку (2026-09-30): разорванные десятичные, сломанный \\frac, ASCII-знаки; попутно проверены ключи и варианты этих задач"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G10_TB_§8_8_4_2", r"объяснения дистракторов 1 и 3 были искажены («0,\dfrac{0016}{4}»); ключ $0{,}2$ верен: $0{,}2^{4}=0{,}0016$",
  dnew={0: (r"$0{,}4$", r"Ученик дважды извлёк квадратный корень и ошибся во втором шаге: $\sqrt{0{,}0016}=0{,}04$, а $\sqrt{0{,}04}=0{,}2$, не $0{,}4$."),
        2: (r"$0{,}016$", r"Ученик сдвинул запятую на один разряд вместо извлечения корня; корень четвёртой степени из $0{,}0016$ равен $0{,}2$, так как $0{,}2^{4}=0{,}0016$.")})
E("G10_TB_§8_8_5_3", r"в объяснениях были разорванные десятичные («$0$,$5$») и символ ∛ вместо \sqrt[3]; ключ $-2$ верен",
  dnew={0: (r"$4$", r"Ученик потерял знак минус: $\sqrt[3]{-64}=-4$, а не $4$; кроме того, забыл умножить на $0{,}5$."),
        1: (r"$-4$", r"Ученик верно нашёл $\sqrt[3]{-64}=-4$, но не умножил на $0{,}5$: $0{,}5\cdot(-4)=-2$."),
        2: (r"$2$", r"Ученик потерял знак минус: $\sqrt[3]{-64}=-4$, поэтому $0{,}5\cdot(-4)=-2$, а не $2$.")})
E("G11_TB_22_6_8", r"в объяснении были разорванные десятичные и неверное округление: $\sqrt[3]{0{,}875}\approx0{,}956$; ключ $0{,}5$ верен: $1-(1-p)^{3}=0{,}875$",
  dnew={2: (r"$0{,}956$", r"Ученик извлёк кубический корень из $0{,}875$ — вероятности хотя бы одного попадания; нужно сначала перейти к вероятности трёх промахов: $(1-p)^{3}=0{,}125$, откуда $p=0{,}5$.")})
E("G5_TB_33_1277.1", r"ключ был записан с разорванной запятой («$40$,$0$»); дистрактор «40» совпадал с ключом по значению; объяснения двух других дистракторов считали не те числа. $CD=9{,}34$, $BC=11{,}65$, $AD=12{,}85$, $P=40{,}04\approx40{,}0$ дм",
  k=r"$40{,}0$ дм",
  dnew={0: (r"$30{,}8$ дм", r"Ученик неверно понял «$CD$ меньше $BC$ на $2{,}31$» и вычел: $BC=9{,}34-2{,}31=7{,}03$; тогда $AD=8{,}23$ и $P=30{,}8$ дм. Верно $BC=9{,}34+2{,}31=11{,}65$."),
        1: (r"$38{,}8$ дм", r"Ученик принял $AD$ равной $BC$ и не прибавил $1{,}2$ дм: $P=6{,}2+9{,}34+11{,}65+11{,}65\approx38{,}8$ дм; верно $AD=12{,}85$ дм."),
        2: (r"$21{,}2$ дм", r"Ученик перепутал «больше» и «меньше» и нашёл $CD=6{,}2-3{,}14=3{,}06$ дм; верно $CD=6{,}2+3{,}14=9{,}34$ дм.")})
E("G5_TB_64_1526.2", r"ключ был записан с разорванной запятой («$172$,$84$»), единица «км» была только у ключа — ответ выделялся по формату; $29{,}8\cdot5{,}8=172{,}84$",
  k=r"$172{,}84$ км",
  dval={0: r"$1728{,}4$ км", 2: r"$172{,}64$ км"},
  dnew={1: (r"$5{,}14$ км", r"Ученик разделил скорость на время ($29{,}8:5{,}8\approx5{,}14$) вместо умножения: путь равен скорости, умноженной на время.")})
E("G8_ALG_13_206.4", r"в объяснении были «<=» и искажённый текст («б $ó$ льшим»); ключ $1$ верен: $x\le1{,}05$",
  dnew={1: (r"$0$", r"Ученик округлил $1{,}05$ вниз и взял $0$; но число $1$ тоже удовлетворяет неравенству ($1\le1{,}05$) и больше $0$.")})
E("G8_ALG_32_558.2", r"в объяснении знаки записаны как «'>'» и «'>='»; ключ верен: $9x>2$ и $x\le10$",
  dnew={0: (r"$\dfrac{2}{9}\le x\le10$", r"Ученик заменил строгий знак нестрогим: из $7(x+1)-2x>9-4x$ получается $x>\dfrac{2}{9}$, граница $\dfrac{2}{9}$ не входит.")})
E("G9_TB_1_7_6", r"дистрактор $2{,}26(6)$ равен ключу $2{,}2(6)$ по значению (оба $2{,}2666\ldots$) — заменён на неверный; объяснение содержало разорванные десятичные",
  dnew={1: (r"$2{,}(6)$", r"Ученик потерял цифру $2$ перед периодом: $\dfrac{4}{15}=0{,}2666\ldots=0{,}2(6)$, поэтому $2\dfrac{4}{15}=2{,}2(6)$, а $2{,}(6)=2{,}666\ldots$.")})
E("G9_TB_ТЗГ1_9", r"спрашивается «найдите эти числа» — ключ «$80$» дополнен до пары; дистрактор $155$ имел объяснение про другие числа; $S(x)=x^{3}+(160-x)^{3}$, $S'(x)=0$ при $x=80$",
  k=r"$80$ и $80$",
  dnew={0: (r"$60$ и $100$", r"Ученик подобрал пару без исследования функции; $60^{3}+100^{3}=1\,216\,000$ больше, чем $80^{3}+80^{3}=1\,024\,000$."),
        1: (r"$75$ и $85$", r"Ученик верно получил $x=80$ из $S'(x)=3x^{2}-3(160-x)^{2}=0$, но затем отступил от него на $5$ в обе стороны; $75^{3}+85^{3}=1\,036\,000>1\,024\,000$."),
        2: (r"$0$ и $160$", r"Ученик решил, что сумма кубов наименьшая при максимальной разнице чисел; но числа положительны, а наименьшее значение — при равных числах $80$ и $80$.")})
E("GEN_G6_S10_03_C_03", r"неверный ключ: второй робот красит $\dfrac{3}{14}-\dfrac{1}{21}=\dfrac{1}{6}$, вместе за час $\dfrac{3}{14}+\dfrac{1}{6}=\dfrac{8}{21}$, осталось $\dfrac{13}{21}$ — числитель $13$ (в ключе было $16$, и $13$ не было среди вариантов); объяснения содержали сломанный \frac",
  k=r"$13$",
  dnew={0: (r"$8$", r"Ученик нашёл покрашенную за час часть $\dfrac{8}{21}$ и записал её числитель; спрашивается оставшаяся часть $1-\dfrac{8}{21}=\dfrac{13}{21}$."),
        1: (r"$16$", r"Ученик записал числитель несокращённой покрашенной части $\dfrac{16}{42}$; спрашивается оставшаяся часть $\dfrac{13}{21}$."),
        2: (r"$31$", r"Ученик прибавил к производительности первого робота разность $\dfrac{1}{21}$ вместо производительности второго: $1-\left(\dfrac{3}{14}+\dfrac{1}{21}\right)=\dfrac{31}{42}$.")})
E("GEN_G6_S44_04_A_04", r"варианты ответа не совпадали с дистракторами (у «$7$.$5$ дм» и «$45$ дм» не было объяснений, дистрактор «0» не показывался); варианты пересобраны; ключ $15$ дм верен: противоположные стороны прямоугольника равны",
  dnew={0: (r"$7{,}5$ дм", r"Ученик решил, что $NP$ вдвое короче $KM$; в прямоугольнике противоположные стороны равны: $NP=KM=15$ дм."),
        1: (r"$30$ дм", r"Ученик удвоил $KM$, приняв её за половину стороны; противоположные стороны прямоугольника равны: $NP=15$ дм."),
        2: (r"$15\sqrt{2}$ дм", r"Ученик нашёл диагональ квадрата со стороной $15$ дм; $NP$ — сторона, противоположная $KM$, и равна ей.")})
